 * @param {number} time - Current time in milliseconds.
 */
function animateWalkingLegs(time) {
    // Find the person who is currently walking (i.e., not inside elevator or actively moving)
    const walkingPerson = people.find(p => p.userData.isWalking && !p.userData.inElevator);
    if (!walkingPerson || !walkingPerson.userData.leftLeg || !walkingPerson.userData.rightLeg) return;

    const legs = walkingPerson.userData;
    const phase = time * 0.005; // Adjust speed of walking animation

    // Left leg: swing forward (positive X)
    legs.leftLeg.rotation.x = Math.sin(phase) * Math.PI / 4;
    // Right leg: swing backward (negative X)
    legs.rightLeg.rotation.x = Math.sin(phase + Math.PI) * Math.PI / 4;
