    const startTime = Date.now();
    const duration = 800; // ms

    const animateDoor = (time) => {
        const elapsed = time - startTime;
        const progress = Math.min(1, elapsed / duration);

        // Doors slide on X axis
        // Left Door: Slides left (negative X) when opening
        const currentXLeft = -doorLength + (open ? (doorDistance - doorLength) * progress : 0);
        // Right Door: Slides right (positive X) when opening
        const currentXRight = doorLength + (open ? (doorDistance - doorLength) * progress : 0);

        doors.leftDoor.position.x = currentXLeft;
        doors.rightDoor.position.x = currentXRight;

        if (progress < 1) {
            requestAnimationFrame(() => animateDoor(Date.now()));
        } else {
            doorAnimationRunning = false;
            done(open);
        }
    };

    requestAnimationFrame(() => animateDoor(Date.now()));
}


